import {shops,products,decks,results,assetKey,styleNames,styleEnglish,puzzleOrder,exploreStyleOrder,exploreCounts,popularShops,newShops,demoPin,shopOpenAt,dateInSeoul,slotsForDate} from './advanced-data.js';
import {createTasteSession,decideTaste,browseTaste,tasteProgress,analyzeTaste,setStyleFilter,pinState,mergeSaved,validateReservation,validateSignup} from './advanced-domain.js';
const app=document.querySelector('#app');
const esc=value=>String(value??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const read=(key,fallback,storage=localStorage)=>{try{return JSON.parse(storage.getItem(key))??fallback;}catch{return fallback;}};
const initial=()=>({guest:{shops:[],products:[],recent:[],reservations:[],deliveries:[]},accounts:{},gender:'all',taste:null,filters:{styleTags:[],distanceMeters:null,openNow:false,tasteMatch:false,savedOnly:false,search:''}});
let data={...initial(),...read('nw3-data',{})};
let auth=read('nw3-auth',null,sessionStorage)??read('nw3-auth',null);
if(new URL(location.href).searchParams.get('demo')==='1'&&!data.demoSeeded){data.guest.shops=mergeSaved(data.guest.shops,['otuvintage','ryohe','ototo']);data.demoSeeded=true;try{localStorage.setItem('nw3-data',JSON.stringify(data));}catch{}}
let assets={};try{const response=await fetch('/public/figma/assets.json');if(response.ok)assets=await response.json();}catch{}
let cleanup=[],busy=false,rotation=0,panel='',selected='afterdark',mapPose={scale:1,x:0,y:0},region='서울',listFilter='전체',shopCategory='전체',storyIndex=0;
const galleryState={};const scrollPositions=new Map();let activeRoute='';
const route=()=>{const [view='start',id='',sub='']=location.hash.replace(/^#\/?/,'').split('/');return {view:view||'start',id,sub,path:location.hash.slice(1)||'/start'};};
const money=n=>'₩'+Number(n).toLocaleString('ko-KR');
const persist=()=>{try{localStorage.setItem('nw3-data',JSON.stringify(data));}catch{toast('저장 공간을 사용할 수 없어요.');}};
const bucket=()=>{if(!auth)return data.guest;return data.accounts[auth.id]??=(initial().guest);};
const shopBy=id=>shops.find(s=>s.id===id);
const productBy=id=>products.find(p=>p.id===id);
const ownProduct=s=>products.find(p=>p.shopId===s.id);
const result=()=>{if(!data.taste)return null;const r=analyzeTaste(data.taste,decks[data.taste.gender]);return results.find(x=>x.id===r.category?.id)??null;};
const recommendIds=()=>{const category=data.taste?analyzeTaste(data.taste,decks[data.taste.gender]).category:null;return category?shops.filter(s=>s.styleTags.some(t=>category.tags.includes(t))).map(s=>s.id):[];};
const schedule=(fn,ms)=>{const timer=setTimeout(fn,ms);cleanup.push(()=>clearTimeout(timer));};
function toast(text){const el=document.querySelector('#toast');el.textContent=text;el.classList.add('visible');clearTimeout(toast.timer);toast.timer=setTimeout(()=>el.classList.remove('visible'),3500);}
function go(path){if(activeRoute)scrollPositions.set(activeRoute,window.scrollY);if(route().path!==path)history.pushState({nw:{previous:route().path}},'', '#'+path);storyIndex=0;panel='';render();}
function back(fallback='/map'){if(history.state?.nw?.previous)history.back();else go(fallback);}
const paths={back:'m15 4-8 8 8 8',arrow:'M4 12h15m-6-6 6 6-6 6',close:'m6 6 12 12M6 18 18 6',heart:'M20.8 4.6a5.5 5.5 0 0 0-7.8 0L12 5.7l-1.1-1.1a5.5 5.5 0 0 0-7.8 7.8L12 21l8.8-8.6a5.5 5.5 0 0 0 0-7.8Z',bookmark:'M6 3h12v18l-6-4-6 4V3Z',home:'m3 10 9-8 9 8v11h-6v-7H9v7H3V10Z',search:'m21 21-5-5M18 10a8 8 0 1 1-16 0 8 8 0 0 1 16 0Z',pin:'M20 10c0 6-8 12-8 12S4 16 4 10a8 8 0 1 1 16 0ZM15 10a3 3 0 1 1-6 0 3 3 0 0 1 6 0Z',user:'M20 21v-2a8 8 0 0 0-16 0v2M16 6a4 4 0 1 1-8 0 4 4 0 0 1 8 0Z',eye:'M2 12s4-6 10-6 10 6 10 6-4 6-10 6-10-6-10-6Zm13 0a3 3 0 1 1-6 0 3 3 0 0 1 6 0Z',lock:'M6 10V7a6 6 0 0 1 12 0v3M4 10h16v12H4V10Zm8 4v4',check:'m5 12 4 4L20 5',clock:'M12 5v7l5 3M22 12a10 10 0 1 1-20 0 10 10 0 0 1 20 0Z',phone:'m3 3 4-1 3 6-3 3c2 3 3 4 6 6l3-3 6 3-1 4C10 25-1 14 3 3Z',instagram:'M7 2h10a5 5 0 0 1 5 5v10a5 5 0 0 1-5 5H7a5 5 0 0 1-5-5V7a5 5 0 0 1 5-5Zm10 10a5 5 0 1 1-10 0 5 5 0 0 1 10 0ZM18 5h.01',locate:'M12 1v4m0 14v4M1 12h4m14 0h4M21 12a9 9 0 1 1-18 0 9 9 0 0 1 18 0ZM16 12a4 4 0 1 1-8 0 4 4 0 0 1 8 0Z',bell:'M5 16h14l-2-4V7a5 5 0 0 0-10 0v5l-2 4Zm5 4h4',settings:'m10 2 4 0 1 3 3 1 3-1 2 4-2 2v3l2 2-2 4-3-1-3 1-1 3h-4l-1-3-3-1-3 1-2-4 2-2v-3L1 9l2-4 3 1 3-1 1-3ZM16 12a4 4 0 1 1-8 0 4 4 0 0 1 8 0Z'};
const icon=(name,filled=false)=>`<svg aria-hidden="true" viewBox="0 0 24 24" fill="${filled?'currentColor':'none'}" stroke="currentColor" stroke-width="1.7" stroke-linecap="round" stroke-linejoin="round"><path d="${paths[name]??paths.arrow}"/></svg>`;
const btn=(action,text,cls='',extra='')=>`<button type="button" class="${cls}" data-action="${action}" ${extra}>${text}</button>`;
const link=(path,text,cls='',extra='')=>`<a href="#${path}" class="${cls}" ${extra}>${text}</a>`;
const ext=(url,text,cls='')=>`<a href="${esc(url)}" class="${cls}" target="_blank" rel="noopener noreferrer">${text}</a>`;
function photo(key,alt='',cls=''){
 const entry=assets[key],url=typeof entry==='string'?entry:entry?.src;
 if(!url||!url.startsWith('/public/figma/')||url.includes('..'))return `<span class="photo asset-missing ${cls}" data-asset="${esc(key)}" role="img" aria-label="${esc(alt)} — 원본 이미지 미연결"><span>원본 이미지 준비 중</span></span>`;
 const style=entry?.position?` style="object-position:${esc(entry.position)}"`:'';
 return `<span class="photo ${cls}" data-asset="${esc(key)}"><img src="${esc(url)}" alt="${esc(alt)}" loading="lazy" draggable="false"${style}></span>`;
}
function nav(active){return `<nav class="bottom-nav" aria-label="주 메뉴">${[['map','홈','home'],['explore','탐색','search'],['upload','업로드','pin'],['saved','저장','heart'],['my','마이','user']].map(([path,label,i])=>link('/'+path,icon(i,path===active)+`<span>${label}</span>`,active===path?'active':'',active===path?'aria-current="page"':'')).join('')}</nav>`;}
const brand=()=>'<div class="brand">NEARWEAR</div>';
const backbar=(title='',fallback='/map',right='')=>`<header class="backbar">${btn('back',icon('back'),'icon-button',`aria-label="뒤로가기" data-fallback="${fallback}"`)}<span>${title}</span>${right}</header>`;
const saveButton=(id,kind='shops')=>{const on=bucket()[kind].includes(id);return btn('save',icon(kind==='shops'?'bookmark':'heart',on),'icon-button save-button'+(on?' saved':''),`data-id="${id}" data-kind="${kind}" aria-label="${kind==='shops'?'매장':'상품'} ${on?'저장 해제':'저장'}" aria-pressed="${on}"`);};
const storyCircles=s=>`<div class="story-circles">${['new','today','sale','info'].map(t=>link(`/story/${s.id}/${t}`,photo(assetKey('logo',s.id),s.name)+`<span>${t.toUpperCase()}</span>`)).join('')}</div>`;
const shopTabs=(s,tab)=>`<nav class="shop-tabs" aria-label="매장 탭">${[['feed','피드'],['products','상품'],['info','안내']].map(([id,label])=>link(`/shop/${s.id}/${id}`,label,tab===id?'active':'',tab===id?'aria-current="page"':'')).join('')}</nav>`;
function start(){return `<main class="start">${btn('start','NEARWEAR','start-logo','aria-label="NEARWEAR 시작"')}</main>`;}
function gender(){return `<main class="gender"><section><p>어떤 옷이 당신의 취향인가요?</p><div>${['womens','mens','all'].map(g=>btn('gender',g.toUpperCase(),data.gender===g?'selected':'',`data-id="${g}"`)).join('')}</div></section></main>`;}
function taste(){
 if(!data.taste)data.taste=createTasteSession(data.gender,decks[data.gender]);
 if(tasteProgress(data.taste).complete){schedule(()=>go('/result'),0);return '';}
 const cards=decks[data.taste.gender],progress=tasteProgress(data.taste);
 return `<main class="taste-screen"><div class="taste-status">${btn('back',icon('back'),'icon-button','data-fallback="/gender" aria-label="뒤로가기"')}<span aria-live="polite">${progress.count} / 12</span></div><div class="taste-stage" aria-label="드래그로 탐색, SKIP 또는 LIKE로 선택"><div class="taste-cylinder">${cards.map((c,i)=>`<div class="taste-card" style="--angle:${i*30}deg" data-card="${c.id}">${photo(c.key,c.description)}<span class="decision-mark">${data.taste.decisions[c.id]==='like'?icon('heart',true):''}</span></div>`).join('')}</div></div><div class="taste-actions">${btn('decide','SKIP','','data-choice="skip"')}${btn('decide','LIKE','','data-choice="like"')}</div></main>`;
}
function resultView(){const r=result();return `<main class="result-view"><p>당신을 위한 스타일</p><h1>${r?esc(r.title):'선호 선택 없음'}</h1><div class="result-photos">${r?Array.from({length:4},(_,i)=>photo(assetKey('result',r.id,i+1),`${r.title} 스타일 ${i+1}`)).join(''):''}</div><p class="result-description">${r?esc(r.description):'아직 좋아요를 선택하지 않았어요. 다양한 매장을 둘러보세요.'}</p>${link('/map','취향에 맞는 매장 찾기 '+icon('arrow'),'button primary')}</main>`;}
function mapView(previewId){
 const f=data.filters,s=shopBy(previewId),distance=f.distanceMeters===null?'전체':f.distanceMeters===500?'500m':f.distanceMeters/1000+'km';
 return `<main class="map-page"><header class="map-header">${brand()}<div class="map-title"><h1>연남 · 연희</h1>${btn('locate',icon('locate'),'icon-button','aria-label="현재 위치 확인"')}</div><label class="search-box">${icon('search')}<input id="map-search" type="search" value="${esc(f.search)}" placeholder="매장, 스타일, 동네 검색" aria-label="매장 검색"></label><div class="map-filters">${btn('panel',f.styleTags.length?'스타일 '+f.styleTags.length+'개':'전체매장',panel==='style'?'active':'','data-id="style" aria-expanded="'+(panel==='style')+'"')}${btn('toggle','영업 중',f.openNow?'active':'','data-id="openNow" aria-pressed="'+f.openNow+'"')}${btn('panel',distance+'⌄',panel==='distance'?'active':'','data-id="distance" aria-expanded="'+(panel==='distance')+'"')}</div>${panel==='style'?`<div class="filter-panel styles">${btn('style','전체매장','','data-id=""')}${styleNames.map(tag=>btn('style',esc(tag)+(f.styleTags.includes(tag)?'<span>✓</span>':''),'',`data-id="${tag}" aria-pressed="${f.styleTags.includes(tag)}"`)).join('')}</div>`:''}${panel==='distance'?`<div class="filter-panel distances">${[[null,'전체'],[500,'500m'],[3000,'3km'],[5000,'5km'],[10000,'10km']].map(([id,label])=>btn('distance',label+(f.distanceMeters===id?'<span>✓</span>':''),'',`data-id="${id??''}"`)).join('')}</div>`:''}${panel!=='style'?`<div class="selected-styles">${f.styleTags.map(t=>btn('style',esc(t)+' ×','',`data-id="${t}" aria-label="${t} 필터 해제"`)).join('')}</div>`:''}</header><div class="map-canvas" id="map-canvas"><div class="map-scene">${assets[assetKey('map','background')]?photo(assetKey('map','background'),'연남·연희 지도','map-background'):'<div class="map-unavailable">지도 원본 이미지 준비 중</div>'}<div id="map-pins">${mapPins()}</div></div></div><p class="map-demo">시연 지도 · 실제 위치와 거리 아님</p><div class="map-controls">${btn('toggle','내 취향 추천',f.tasteMatch?'active':'','data-id="tasteMatch" aria-pressed="'+f.tasteMatch+'"')}${btn('toggle','저장',f.savedOnly?'active':'','data-id="savedOnly" aria-pressed="'+f.savedOnly+'"')}</div><div class="zoom-controls">${btn('zoom','+','','data-step="1" aria-label="지도 확대"')}${btn('zoom','−','','data-step="-1" aria-label="지도 축소"')}</div>${nav('map')}${s?preview(s):''}</main>`;
}
function mapPins(){const f=data.filters,recommended=recommendIds();return [...shops,demoPin].filter(s=>(!f.search||(s.name+' '+s.address+' '+s.styleTags.join(' ')).toLowerCase().includes(f.search.toLowerCase()))&&(!f.styleTags.length||f.styleTags.some(t=>s.styleTags.includes(t)))&&(!f.openNow||(s.hasDetail&&shopOpenAt(s)))&&(!f.tasteMatch||recommended.includes(s.id))&&(!f.savedOnly||bucket().shops.includes(s.id))&&f.distanceMeters===null).map(s=>{
 const status=pinState({...s,openNow:s.hasDetail&&shopOpenAt(s)},{selectedId:selected,savedIds:bucket().shops,recommendedIds:recommended,showOpen:f.openNow,showSaved:f.savedOnly,showTaste:f.tasteMatch});
 return btn('pin',`<span class="pin-shape"></span><span class="pin-label">${s.name}</span>`,'map-pin '+status.primary,`data-id="${s.id}" style="left:${s.position[0]}%;top:${s.position[1]}%" aria-label="${s.name}${selected===s.id?' 선택됨':''}"`);
 }).join('')||'<p class="map-empty">조건에 맞는 매장이 없어요.</p>';}
function preview(s){const selectedPhoto=galleryState['preview-'+s.id]??1;return `<div class="sheet-backdrop" data-action="close-preview"></div><section class="preview-sheet" role="dialog" aria-modal="true" aria-label="${s.name} 미리보기"><button class="sheet-handle" data-action="close-preview" aria-label="미리보기 닫기"></button><div class="preview-hero">${photo(assetKey('gallery',s.id,selectedPhoto),s.name+' 매장 사진')}</div><div class="shop-name"><h1>${s.name}</h1>${saveButton(s.id)}</div><p class="shop-styles">${s.styleTags.join(' · ')}</p><div class="open-line"><span class="${shopOpenAt(s)?'open':''}">● ${shopOpenAt(s)?'영업 중':'영업 종료'}</span><span>${icon('pin')} 위치 권한 필요</span></div><div class="preview-thumbs">${Array.from({length:s.galleryCount},(_,i)=>btn('preview-photo',photo(assetKey('gallery',s.id,i+1),`${s.name} 사진 ${i+1}`),selectedPhoto===i+1?'active':'',`data-id="${s.id}" data-index="${i+1}" aria-label="사진 ${i+1}"`)).join('')}</div><p class="address-box">${icon('pin')}${esc(s.address)}</p>${link(`/shop/${s.id}/feed`,'상세보기 '+icon('arrow'),'button outline')}</section>`;}
function shopView(s,tab='feed'){
 if(!s)return missing();
 if(tab==='info')return `<main class="shop-info light">${shopTabs(s,tab)}<section class="info-heading"><h1>${s.name}</h1><p>${s.styleTags.join(' / ')}</p>${storyCircles(s)}</section><section class="store-info"><h2>STORE INFO</h2><p>${icon('pin')}<span>${esc(s.address)}</span></p><p>${icon('clock')}<span>${esc(s.hours)}</span></p>${s.phone?`<p>${icon('phone')}<a href="tel:${s.phone}">${s.phone}</a></p>`:''}<p>${icon('instagram')}${ext(`https://www.instagram.com/${s.instagram}/`,'@'+s.instagram)}</p><div class="info-map">${photo(assetKey('map','info'),'매장 위치 지도')}</div>${ext(s.naverUrl,'지도에서 보기','button outline')}</section>${nav('map')}</main>`;
 if(tab==='products')return `<main class="catalog light">${shopTabs(s,tab)}<nav class="category-tabs">${['전체','상의','하의','잡화','액세서리'].map(t=>btn('category',t,shopCategory===t?'active':'',`data-id="${t}"`)).join('')}</nav><div class="catalog-grid">${catalog(s)}</div>${nav('map')}</main>`;
 const image=galleryState['shop-'+s.id]??1;
 return `<main class="shop-feed light"><div class="shop-hero">${photo(assetKey('gallery',s.id,image),s.name+' 매장 사진')}${btn('back',icon('back'),'hero-back icon-button','aria-label="뒤로가기" data-fallback="/map"')}${s.galleryCount>1?`<div class="hero-controls">${btn('shop-photo','‹','',`data-id="${s.id}" data-step="-1" aria-label="이전 사진"`)}<span>${image} / ${s.galleryCount}</span>${btn('shop-photo','›','',`data-id="${s.id}" data-step="1" aria-label="다음 사진"`)}</div>`:''}</div><div class="shop-name"><h1>${s.name}</h1>${saveButton(s.id)}</div><p class="shop-subtitle">${s.id==='gowon'?'빈티지 구제 의류':'빈티지 스토어'}</p><p class="shop-address">${icon('pin')}${esc(s.address)}</p>${storyCircles(s)}${shopTabs(s,'feed')}<div class="feed-grid">${Array.from({length:15},(_,i)=>btn('feed-photo',photo(assetKey('feed',s.id,i+1),`${s.name} 피드 ${i+1}`),'',`data-id="${s.id}" data-index="${i+1}" aria-label="${s.name} 피드 ${i+1}"`)).join('')}</div></main>`;
}
function catalog(s){const p=ownProduct(s);if(shopCategory!=='전체')return p.category===shopCategory?link('/product/'+p.id,photo(assetKey('catalog',s.id,p.catalogIndex),p.name),'catalog-item',`aria-label="${esc(p.name)}"`):'<p class="empty">등록된 상품이 없어요.</p>';
 return Array.from({length:15},(_,i)=>{const image=photo(assetKey('catalog',s.id,i+1),i+1===p.catalogIndex?p.name:`${s.name} 상품 ${i+1}`);return i+1===p.catalogIndex?link('/product/'+p.id,image,'catalog-item',`aria-label="${esc(p.name)}"`):btn('unavailable',image,'catalog-item',`aria-label="${s.name} 상품 ${i+1}: 상세 준비 중"`);}).join('');}
function productView(p){if(!p)return missing();const image=galleryState['product-'+p.id]??0;return `<main class="product-page">${backbar('상품 상세','/shop/'+p.shopId+'/products')}<div class="product-hero">${photo(image?assetKey('product',p.id,image):assetKey('product-hero',p.id),p.name)}</div><section class="product-card"><div class="product-title"><h1>${p.name}</h1>${saveButton(p.id,'products')}</div><strong class="product-price">${money(p.price)}</strong><div class="product-thumbs">${Array.from({length:p.photoCount},(_,i)=>btn('product-photo',photo(assetKey('product',p.id,i+1),p.name+` 사진 ${i+1}`),'',`data-id="${p.id}" data-index="${i+1}" aria-label="상품 사진 ${i+1}"`)).join('')}</div><dl>${[['브랜드',p.brand],['카테고리',p.category],['소재',p.material],['사이즈',p.size],['색상',p.color],['하자',p.flaws],['배송',p.shipping]].map(([label,value])=>`<div><dt>${label}</dt><dd>${esc(value)}</dd></div>`).join('')}</dl><div class="product-cta">${link('/delivery/'+p.id,'당일 배송','button outline')}${link('/reserve/'+p.id,'방문 예약','button dark')}</div></section></main>`;}
function storyView(s,type){if(!s||!['new','today','sale','info'].includes(type))return missing();const count=type==='new'?s.newCount:type==='sale'?s.saleCount:1;storyIndex=Math.max(0,Math.min(count-1,storyIndex));const descriptions={new:'오늘 들어온 제품들을 편하게 둘러보세요.',today:s.range.join(' ~ '),sale:'선택 상품 최대 20% 할인. 가격은 상품 페이지를 확인하세요.',info:'피팅 가능합니다. 제품 예약과 배송이 가능한 매장입니다.'};
 return `<main class="story-page">${s.id==='ttul'&&type==='info'?'':photo(assetKey('story-'+type,s.id,storyIndex+1),`${s.name} ${type} ${storyIndex+1}`,'story-photo')}<div class="story-shade"></div><header class="story-header"><div class="story-progress">${Array.from({length:count},(_,i)=>`<span class="${i<=storyIndex?'seen':''}"></span>`).join('')}</div><div class="story-byline">${photo(assetKey('logo',s.id),s.name)}<div><b>${s.name}</b><small>${({new:'신상품 · 2시간 전',today:'오늘 · 3시간 전',sale:'할인 · 5시간 전',info:'안내 · 1일 전'})[type]}</small></div>${link(`/shop/${s.id}/feed`,icon('close'),'icon-button','aria-label="스토리 닫기"')}</div></header><div class="story-arrows">${btn('story-step','‹','','data-step="-1" aria-label="이전 스토리"')}${btn('story-step',type==='info'?'✓':'›','','data-step="1" aria-label="다음 스토리"')}</div><section class="story-copy"><h1>${type.toUpperCase()}</h1><p>${descriptions[type]}</p>${['today','info'].includes(type)?link(`/shop/${s.id}/info`,'매장 안내 '+icon('arrow'),'button dark'):btn('story-product','상품 보기 '+icon('arrow'),'button primary',`data-id="${s.id}" data-type="${type}" data-index="${storyIndex}" ${s.id==='ototo'&&type==='new'&&storyIndex===1?'':'disabled aria-label="상품 연결 준비 중"'}`)}</section></main>`;
}
function login(){return `<main class="auth-page">${backbar('', '/my')}<h1>로그인</h1><p class="auth-intro">NEARWEAR와 함께<br>당신의 취향을 이어가세요.</p><form id="login-form" novalidate><label class="sr-only" for="login-email">이메일 주소</label><input id="login-email" name="email" type="email" placeholder="이메일 주소" autocomplete="username" required><div class="password-field"><label class="sr-only" for="login-password">비밀번호</label><input id="login-password" name="password" type="password" placeholder="비밀번호" autocomplete="current-password" required>${btn('eye',icon('eye'),'icon-button','aria-label="비밀번호 보기" aria-pressed="false"')}</div><div class="login-options"><label><input type="checkbox" name="remember"> 로그인 상태 유지</label>${btn('password-help','비밀번호 찾기','text-link')}</div><p class="demo-note">시연용 로그인 · 실제 계정 인증이 아닙니다.<br>실사용 이메일과 비밀번호를 입력하지 마세요.</p><p class="form-error" role="alert"></p><button class="button primary" type="submit">로그인하기</button></form><div class="or"><span>또는</span></div><div class="social-buttons">${btn('social','<span class="social-icon apple"><svg viewBox="0 0 24 24" aria-hidden="true"><path fill="currentColor" d="M17.05 20.28c-.98.95-2.05.8-3.08.35-1.09-.46-2.09-.48-3.24 0-1.44.62-2.2.44-3.06-.35C2.79 15.25 3.51 7.59 9.05 7.31c1.35.07 2.29.76 3.08.82 1.18-.24 2.31-.94 3.57-.85 1.51.12 2.65.72 3.4 1.81-3.12 1.87-2.38 5.96.48 7.11-.57 1.5-1.31 3-2.54 4.09l.01-.01ZM12.03 7.25C11.88 5.02 13.69 3.18 15.77 3c.29 2.58-2.34 4.5-3.74 4.25Z"/></svg></span>Apple로 계속하기','button outline','data-provider="Apple"')}${btn('social','<b class="google">G</b>Google로 계속하기','button outline','data-provider="Google"')}${btn('social','<span class="social-icon kakao"><svg viewBox="0 0 36 36" aria-hidden="true"><circle cx="18" cy="18" r="16" fill="#fce500"/><path d="M18 9c-6 0-11 3.6-11 8.1 0 2.8 1.8 5.3 4.8 6.7l-1.2 4.6 5-3.2 2.4.2c6 0 11-3.7 11-8.3S24 9 18 9Z" fill="#080b05"/></svg></span>카카오로 계속하기','button outline','data-provider="카카오"')}</div><p class="auth-footer">계정이 없으신가요? ${link('/signup','회원가입하기')}</p></main>`;}
function signup(){return `<main class="auth-page signup-page">${backbar('','/login')}<h1>회원가입</h1><p class="auth-intro">나만의 빈티지 취향을<br>NEARWEAR에 저장해보세요.</p><form id="signup-form" novalidate>${[['email','이메일 주소','email'],['password','비밀번호 (8자 이상)','password'],['confirmation','비밀번호 확인','password'],['nickname','닉네임 (선택)','text']].map(([name,label,type])=>`<label class="sr-only" for="signup-${name}">${label}</label><input id="signup-${name}" name="${name}" type="${type}" placeholder="${label}" autocomplete="${type==='password'?'new-password':'off'}" ${name==='nickname'?'maxlength="30"':'required'}>`).join('')}<div class="consents">${[['age','만 14세 이상이며, 아래 내용에 동의합니다.'],['terms','이용약관 (필수)'],['privacy','개인정보 수집 및 이용 동의 (필수)'],['marketing','마케팅 정보 수신 동의 (선택)']].map(([name,label])=>`<label><input type="checkbox" name="${name}"><span>${label}</span></label>`).join('')}</div><p class="demo-note">시연용 가입입니다. 실제 계정은 생성되지 않으며,<br>비밀번호·이메일 원문은 저장하지 않습니다.</p><p class="form-error" role="alert"></p><button type="submit" class="button primary">회원가입하기</button></form></main>`;}
function signupComplete(){return `<main class="signup-complete"><section><div class="success-check">${icon('check')}</div><h1>회원가입이 완료되었습니다.</h1><p>NEARWEAR에서<br>더 많은 매장을 발견하고<br>당신만의 취향을 이어가세요.</p></section>${btn('continue','시작하기','button primary')}</main>`;}
function authGate(kind){return `<div class="auth-overlay"><section class="auth-gate" role="dialog" aria-modal="true" aria-labelledby="gate-title">${icon('lock')}<h2 id="gate-title">로그인이 필요해요.</h2><p>${kind==='reserve'?'로그인 후 방문 예약을<br>계속할 수 있어요.':'배송 정보와 주문 내역을<br>저장하기 위해 로그인해주세요.'}</p>${btn('gate-login','로그인하고 계속하기','button primary')}${btn('gate-signup','회원가입','button outline')}${btn('gate-later','나중에 하기','later')}</section></div>`;}
function requestForm(p,kind){if(!p)return missing();const s=shopBy(p.shopId),isReserve=kind==='reserve',draft=read('nw3-draft-'+kind+'-'+p.id,{},sessionStorage),date=draft.date??'',slots=date?futureSlots(s,date):[];return `<main class="request-page">${backbar('', '/product/'+p.id)}<h1>${isReserve?'방문 예약':'당일 배송'}</h1><form id="${kind}-form" class="request-card" data-product="${p.id}" novalidate><div class="request-shop">${photo(assetKey('product-hero',p.id),p.name)}<div><b>${s.name}</b><p>${esc(s.address)}</p></div></div>${isReserve?`<label>예약 날짜<input name="date" type="date" min="${dateInSeoul()}" value="${esc(date)}" required></label><label>방문 시간<select name="time" required><option value="">${date&&!slots.length?'방문 가능한 시간이 없어요':'방문 시간을 선택해주세요.'}</option>${slots.map(t=>`<option ${draft.time===t?'selected':''}>${t}</option>`).join('')}</select></label><label>방문 인원<select name="people"><option value="1">1명</option><option value="2" ${draft.people==='2'?'selected':''}>2명</option><option value="3" ${draft.people==='3'?'selected':''}>3명</option><option value="4" ${draft.people==='4'?'selected':''}>4명</option></select></label><label>방문사유 (선택)<textarea name="reason" maxlength="200" placeholder="간단하게 입력해주세요.">${esc(draft.reason??'')}</textarea></label>`:`<label>배송 유형<select name="type"><option value="same-day">당일 배송 (5시 이전 구매시 당일 도착)</option></select></label><label>배송지 주소<input name="address" placeholder="주소지를 입력해주세요." autocomplete="off" required></label><label>결제 수단<select name="payment" required><option value="">결제수단을 선택해주세요.</option><option value="demo">시연 결제 (실제 결제 없음)</option></select></label><label>요청사항 (선택)<textarea name="note" maxlength="200" placeholder="부재 시 문 앞에 놓아주세요."></textarea></label>`}<p class="demo-note">시연 신청 · 실제 ${isReserve?'매장 예약':'결제·배송'}은 진행되지 않습니다.${!isReserve?'<br>주소와 요청사항은 저장하지 않습니다.':''}</p><p class="form-error" role="alert"></p><button type="submit" class="button dark">${isReserve?'예약하기':'당일 배송 신청하기'}</button><p class="request-result" role="status"></p></form>${auth?'':authGate(kind)}</main>`;}
function futureSlots(s,date){const today=dateInSeoul(),now=new Intl.DateTimeFormat('en-GB',{timeZone:'Asia/Seoul',hour:'2-digit',minute:'2-digit',hourCycle:'h23'}).format(new Date());if(date<today)return [];return slotsForDate(s,date).filter(t=>date!==today||t>now);}
function upload(){const list=['otuvintage','ryohe','ototo',...shops.map(s=>s.id)].filter((id,i,a)=>a.indexOf(id)===i&&bucket().shops.includes(id));return `<main class="upload-page">${brand()}${btn('notifications',icon('bell'),'notifications icon-button','aria-label="알림"')}<h1>STORIES</h1><p class="intro">찜한 매장의 새로운 소식을 확인해보세요.</p>${list.length?list.map(id=>{const s=shopBy(id);if(!s)return '';return `<section class="upload-shop"><header>${photo(assetKey('logo',id),s.name)}<b>${s.name}</b><span class="${shopOpenAt(s)?'open':''}">● ${shopOpenAt(s)?'지금 영업 중':'영업 종료'}</span><small>· 시연 콘텐츠</small>${link('/shop/'+id+'/feed','›','',`aria-label="${s.name} 상세"`)}</header><div class="upload-cards">${['today','new','sale'].map(type=>link(`/story/${id}/${type}`,photo(assetKey('story-'+type,id),s.name+' '+type)+`<div><b>${type.toUpperCase()}</b><small>${type==='today'?s.range.join(' - '):type==='new'?'▢ '+s.newCount:'선택 상품 할인'}</small></div>`)).join('')}</div></section>`;}).join(''):'<p class="empty">찜한 매장이 없어요. 지도에서 매장을 저장해보세요.</p>'}${nav('upload')}</main>`;}
function explore(){return `<main class="explore-page">${brand()}<h1>EXPLORE</h1><nav class="region-tabs">${['전체','서울','인천','경기','부산','대구','대전','광주','제주'].map(r=>btn('region',r,region===r?'active':'',`data-id="${r}"`)).join('')}</nav>${['전체','서울'].includes(region)?`${link('/explore/popular',photo(assetKey('explore','hero'),'지금 눈여겨볼 빈티지샵')+'<div><small>SEOUL</small><h2>지금 눈여겨볼 빈티지샵 '+icon('arrow')+'</h2></div>','explore-hero')}<section><header class="section-title"><h2>스타일별 발견</h2>${link('/explore/styles','전체보기 ›')}</header><div class="style-strip">${exploreStyleOrder.map(i=>link('/explore/styles/'+i,photo(assetKey('explore-style',i),styleNames[i])+`<b>${styleEnglish[i]}</b><span>${styleNames[i]}</span>`)).join('')}</div></section><section><header class="section-title"><h2>새로운 매장</h2>${link('/explore/new','전체보기 ›')}</header>${newShops.slice(0,2).map(exploreRow).join('')}</section>`:'<p class="empty">이 지역의 매장 콘텐츠는 준비 중입니다.</p>'}${nav('explore')}</main>`;}
function exploreRow(s){return `<article class="explore-row">${btn('place-info',photo(assetKey('explore-shop',s.id),s.name),'',`data-id="${s.id}" aria-label="${s.name} 장소 정보"`)}<div><h2>${s.name}</h2><p>${s.styles}</p><address>${icon('pin')}${s.address}</address></div>${saveButton(s.id)}</article>`;}
function exploreList(type,style){if(type==='styles'){return `<main class="style-list">${backbar('스타일별 발견','/explore')}<nav class="pill-tabs">${['전체',...styleNames].map((name,i)=>btn('style-list-filter',name,(style===String(i-1)||(!style&&i===0))?'active':'',`data-id="${i===0?'':i-1}"`)).join('')}</nav><div class="style-grid">${exploreStyleOrder.filter(i=>style===''||style===String(i)).map(i=>btn('style-results',photo(assetKey('explore-style',i),styleNames[i])+`<div><b>${styleEnglish[i]}</b><p>${styleNames[i]}</p><small>${exploreCounts[exploreStyleOrder.indexOf(i)]}개의 매장</small><span>›</span></div>`,'',`data-id="${i}"`)).join('')}</div><p class="demo-note">매장 수는 제공된 디자인의 예시입니다.</p></main>`;}
 const popular=type==='popular';return `<main class="explore-list">${backbar(popular?'지금 눈여겨볼 빈티지샵':'새로운 매장','/explore')}${popular?'<div class="list-intro"><p>최근 많은 사용자들이 방문하고 저장한<br>서울의 인기 빈티지샵을 모았어요.</p><span>최근 인기순⌄</span></div>':`<nav class="pill-tabs">${['전체','신규 오픈','최근 추가','이번 주 인기'].map(t=>btn('new-filter',t,t===listFilter?'active':'',`data-id="${t}"`)).join('')}</nav>`}${popular||listFilter==='전체'?(popular?popularShops:newShops).map(exploreRow).join(''):'<p class="empty">해당 분류의 확인된 정보가 아직 없어요.</p>'}</main>`;}
function savedView(tab='shops'){const b=bucket();return `<main class="saved-page light">${brand()}<h1>SAVED</h1><nav class="saved-tabs">${link('/saved/shops','매장',tab==='shops'?'active':'')}${link('/saved/products','상품',tab==='products'?'active':'')}</nav>${tab==='shops'?b.shops.map(id=>{const s=shopBy(id)??popularShops.concat(newShops).find(s=>s.id===id);if(!s)return '';return `<article class="saved-shop">${s.hasDetail?link('/shop/'+id+'/feed',photo(assetKey('gallery',id),s.name)):btn('place-info',photo(assetKey('explore-shop',id),s.name),'',`data-id="${id}"`)}<div><h2>${s.name}</h2><p>${s.styleTags?.join(' · ')??s.styles}</p><address>${icon('pin')}${esc(s.address)}</address></div>${saveButton(id)}</article>`;}).join('')||'<p class="empty">저장한 매장이 없어요.</p>':`<div class="saved-product-grid">${b.products.map(id=>{const p=productBy(id);if(!p)return '';return `<article>${link('/product/'+id,photo(assetKey('product-hero',id),p.name))}${saveButton(id,'products')}<h2>${p.name}</h2><p>${Number(p.price).toLocaleString('ko-KR')}원</p></article>`;}).join('')||'<p class="empty">저장한 상품이 없어요.</p>'}</div>`}${nav('saved')}</main>`;}
function my(){if(!auth)return `<main class="my-guest">${brand()}<h1>MY</h1><h2>로그인하고<br>당신의 취향을 이어가세요.</h2><p>당신의 취향으로 바구니를 채워보세요</p>${photo(assetKey('my','basket'),'당신의 취향으로 채우는 쇼핑 바구니','my-basket')}${link('/login','로그인','button primary')}${link('/signup','회원가입','button outline')}${nav('my')}</main>`;
 const b=bucket(),r=result();return `<main class="my-page"><header><h1>MY TASTE</h1>${link('/settings',icon('settings'),'icon-button','aria-label="설정"')}</header><h2>${r?esc(r.title):'아직 찾지 않은 취향'}</h2><p class="taste-summary">${r?esc(r.description):'좋아하는 스타일을 찾아보세요.'}</p><div class="taste-links">${link('/gender','취향 재발견','button outline')}${link('/puzzle','내 취향 퍼즐','button outline')}</div><section class="recent"><h3>최근 둘러본 상품</h3><div>${b.recent.map(id=>{const p=productBy(id);return p?link('/product/'+id,photo(assetKey('product-hero',id),p.name)):'';}).join('')||'<p class="empty">최근 본 상품이 없어요.</p>'}</div></section><h3>장바구니 ${b.reservations.length+b.deliveries.length}</h3>${b.reservations.map(record=>recordCard(record,'예약')).join('')}${b.deliveries.map(record=>recordCard(record,'배송')).join('')}${b.reservations.length+b.deliveries.length?'':'<p class="empty">예약·배송 시연 신청 내역이 없어요.</p>'}${nav('my')}</main>`;}
function recordCard(record,type){const p=productBy(record.productId);if(!p)return '';return `<article class="record-card"><small>${esc(record.date??'')} ${esc(record.time??'')}</small><div>${photo(assetKey('product-hero',p.id),p.name)}<section><p>${p.name}</p><strong>${money(p.price)}</strong><span>${record.status==='CANCELLED'?'시연 예약 취소':type+' 시연 신청'}</span></section></div><footer>${shopBy(p.shopId).name} ${record.status==='CANCELLED'?'':type==='예약'?btn('cancel-reservation','예약 취소 ›','',`data-id="${record.id}"`):'배송 신청 확인'}</footer></article>`;}
function puzzle(){const gender=data.taste?.gender??data.gender,cards=decks[gender];return `<main class="puzzle-page">${backbar('내 취향 퍼즐','/my')}<div class="puzzle-grid">${puzzleOrder[gender].map(index=>{const c=cards[index-1],liked=data.taste?.decisions[c.id]==='like';return `<div>${photo(c.key,c.description)}<span class="puzzle-heart">${icon('heart',liked)}</span></div>`;}).join('')}</div><p>다른 취향도 경험해보세요.</p>${link('/gender','취향 재발견 '+icon('arrow'),'button outline')}</main>`;}
function settings(){return `<main class="settings-page">${backbar('','/my',icon('settings'))}<header>${photo(assetKey('my','profile'),'프로필 사진')}<div><h2>${esc(auth?.nickname??'시연 사용자')}</h2><p>시연 계정</p>${btn('setting-info','프로필 수정　›','text-link','data-id="프로필 수정"')}</div></header>${['계정 정보','배송지 관리','알림 설정','개인정보 관리','결제 수단 관리','고객센터','로그아웃'].map(label=>btn(label==='로그아웃'?'logout':'setting-info',esc(label)+'<span>›</span>','settings-row',`data-id="${label}"`)).join('')}</main>`;}
function missing(){return `<main>${backbar('','/map')}<p class="empty">제공된 화면 또는 상품이 없어요.</p>${link('/map','홈으로','button outline')}</main>`;}
function render(){
 clearTimeout(toast.timer);document.querySelector('#toast').classList.remove('visible');
 cleanup.forEach(fn=>fn());cleanup=[];busy=false;const r=route();activeRoute=r.path;
 const s=shopBy(r.id),p=productBy(r.id);
 if(r.view==='product'&&p){const b=bucket();b.recent=[p.id,...b.recent.filter(id=>id!==p.id)].slice(0,8);persist();}
 app.className='app-frame';
 const views={start,gender,taste,result:resultView,map:()=>mapView(),preview:()=>mapView(r.id),shop:()=>shopView(s,r.sub||'feed'),product:()=>productView(p),story:()=>storyView(s,r.sub),login,signup,'signup-complete':signupComplete,reserve:()=>requestForm(p,'reserve'),delivery:()=>requestForm(p,'delivery'),upload,explore:()=>r.id?exploreList(r.id,r.sub):explore(),saved:()=>savedView(r.id||'shops'),my,puzzle,settings};
 app.innerHTML=(views[r.view]??missing)();
 window.scrollTo(0,scrollPositions.get(r.path)??0);
 if(r.view==='start')schedule(()=>go('/gender'),1800);
 if(r.view==='taste')mountCylinder();
 if(['map','preview'].includes(r.view))mountMap();
 if(['reserve','delivery'].includes(r.view)&&!auth){sessionStorage.setItem('nw3-return',r.path);app.querySelectorAll('.request-page > :not(.auth-overlay)').forEach(el=>el.inert=true);app.querySelector('.auth-gate button')?.focus();}
 app.querySelectorAll('img').forEach(img=>img.addEventListener('error',()=>{img.parentElement.classList.add('asset-missing');img.replaceWith(Object.assign(document.createElement('span'),{textContent:'원본 이미지 준비 중'}));},{once:true}));
}
function mountCylinder(){const stage=app.querySelector('.taste-stage'),cylinder=app.querySelector('.taste-cylinder');let start=null,dragged=false,activePointer=null;rotation=decks[data.taste.gender].findIndex(c=>c.id===data.taste.activeImageId);cylinder.style.setProperty('--rotation',`${-rotation*30}deg`);
 const down=e=>{if(busy||activePointer!==null)return;activePointer=e.pointerId;start=e.clientX;dragged=false;stage.setPointerCapture(e.pointerId);};
 const move=e=>{if(e.pointerId!==activePointer)return;const delta=e.clientX-start;if(Math.abs(delta)>12)dragged=true;cylinder.style.setProperty('--rotation',`${-rotation*30+Math.max(-30,Math.min(30,delta/4))}deg`);};
 const up=e=>{if(e.pointerId!==activePointer)return;activePointer=null;const delta=e.clientX-start;if(e.type!=='pointercancel'&&dragged&&Math.abs(delta)>30){data.taste=browseTaste(data.taste,delta<0?1:-1);persist();rotation+=delta<0?1:-1;}cylinder.style.setProperty('--rotation',`${-rotation*30}deg`);};
 stage.addEventListener('pointerdown',down);stage.addEventListener('pointermove',move);stage.addEventListener('pointerup',up);stage.addEventListener('pointercancel',up);
 const key=e=>{if(['ArrowLeft','ArrowRight'].includes(e.key)&&!busy){e.preventDefault();data.taste=browseTaste(data.taste,e.key==='ArrowRight'?1:-1);persist();rotation+=e.key==='ArrowRight'?1:-1;cylinder.style.setProperty('--rotation',`${-rotation*30}deg`);}};
 stage.tabIndex=0;stage.addEventListener('keydown',key);
}
function decide(choice){if(busy||route().view!=='taste')return;const session=data.taste,id=session.activeImageId;if(!id||Object.hasOwn(session.decisions,id)){toast('이미 선택한 이미지예요. 좌우로 탐색해 주세요.');return;}
 busy=true;app.querySelectorAll('[data-action="decide"]').forEach(b=>b.disabled=true);data.taste=decideTaste(session,id,choice);persist();const mark=app.querySelector(`[data-card="${id}"] .decision-mark`);if(choice==='like')mark.innerHTML=icon('heart',true);
 const next=decks[session.gender].findIndex(c=>c.id===data.taste.activeImageId),current=((rotation%12)+12)%12;rotation+=next<0?1:((next-current+12)%12||12);app.querySelector('.taste-cylinder').style.setProperty('--rotation',`${-rotation*30}deg`);
 const ms=matchMedia('(prefers-reduced-motion: reduce)').matches?20:720;
 schedule(()=>{if(tasteProgress(data.taste).complete)go('/result');else{busy=false;const progress=tasteProgress(data.taste);app.querySelector('.taste-status span').textContent=`${progress.count} / 12`;app.querySelectorAll('[data-action="decide"]').forEach(b=>b.disabled=false);}},ms);
}
function mountMap(){const canvas=app.querySelector('#map-canvas'),scene=app.querySelector('.map-scene'),points=new Map();let last=null,moved=false;const paint=()=>scene.style.transform=`translate(${mapPose.x}px,${mapPose.y}px) scale(${mapPose.scale})`;paint();const metrics=()=>{const p=[...points.values()];return p.length===1?{x:p[0].x,y:p[0].y,d:0}:{x:(p[0].x+p[1].x)/2,y:(p[0].y+p[1].y)/2,d:Math.hypot(p[0].x-p[1].x,p[0].y-p[1].y)};};
 const down=e=>{if(e.button>0)return;points.set(e.pointerId,{x:e.clientX,y:e.clientY});last=metrics();moved=false;};
 const move=e=>{if(!points.has(e.pointerId))return;points.set(e.pointerId,{x:e.clientX,y:e.clientY});const current=metrics();if(last){const dx=current.x-last.x,dy=current.y-last.y;if(Math.abs(dx)+Math.abs(dy)>2)moved=true;mapPose.x+=dx;mapPose.y+=dy;if(current.d&&last.d){mapPose.scale=Math.max(.5,Math.min(3,mapPose.scale*current.d/last.d));moved=true;}paint();}last=current;};
 const up=e=>{points.delete(e.pointerId);last=points.size?metrics():null;};const click=e=>{if(moved){e.preventDefault();e.stopImmediatePropagation();moved=false;}};
 const wheel=e=>{e.preventDefault();mapPose.scale=Math.max(.5,Math.min(3,mapPose.scale*Math.exp(-e.deltaY*.002)));paint();};
 canvas.addEventListener('pointerdown',down);window.addEventListener('pointermove',move);window.addEventListener('pointerup',up);window.addEventListener('pointercancel',up);canvas.addEventListener('click',click,true);canvas.addEventListener('wheel',wheel,{passive:false});cleanup.push(()=>{window.removeEventListener('pointermove',move);window.removeEventListener('pointerup',up);window.removeEventListener('pointercancel',up);});
}
async function demoLogin(email,nickname,remember){const buffer=await crypto.subtle.digest('SHA-256',new TextEncoder().encode(email.toLowerCase().trim()));const id='demo-'+Array.from(new Uint8Array(buffer)).map(b=>b.toString(16).padStart(2,'0')).join('');auth={id,nickname:nickname||'시연 사용자'};const b=bucket();for(const key of ['shops','products','recent'])b[key]=mergeSaved(data.guest[key],b[key]);data.guest=initial().guest;persist();localStorage.removeItem('nw3-auth');sessionStorage.setItem('nw3-auth',JSON.stringify(auth));if(remember)localStorage.setItem('nw3-auth',JSON.stringify(auth));}
function continueAfterAuth(){const path=sessionStorage.getItem('nw3-return');sessionStorage.removeItem('nw3-return');go(path&&/^\/(reserve|delivery)\/[a-z0-9-]+$/.test(path)?path:'/my');}
app.addEventListener('click',e=>{
 const anchor=e.target.closest('a[href^="#/"]');if(anchor){e.preventDefault();go(anchor.getAttribute('href').slice(1));return;}
 const b=e.target.closest('[data-action]');if(!b)return;const a=b.dataset.action,id=b.dataset.id,r=route();
 if(a==='start')go('/gender');
 if(a==='back')back(b.dataset.fallback||'/map');
 if(a==='gender'){data.gender=id;data.taste=createTasteSession(id,decks[id]);persist();go('/taste');}
 if(a==='decide')decide(b.dataset.choice);
 if(a==='save'){const owner=bucket(),kind=b.dataset.kind,on=owner[kind].includes(id);owner[kind]=on?owner[kind].filter(x=>x!==id):[...owner[kind],id];persist();if(['saved','upload'].includes(r.view))render();else{const tag=kind==='shops'?'bookmark':'heart';app.querySelectorAll(`[data-action="save"][data-id="${id}"]`).forEach(el=>{el.innerHTML=icon(tag,!on);el.classList.toggle('saved',!on);el.setAttribute('aria-pressed',String(!on));el.setAttribute('aria-label',(kind==='shops'?'매장':'상품')+(!on?' 저장 해제':' 저장'));});}toast(on?'저장을 해제했어요.':'저장했어요.');}
 if(a==='panel'){panel=panel===id?'':id;render();}
 if(a==='style'){if(id&&!data.filters.styleTags.includes(id)&&data.filters.styleTags.length>=5){toast('스타일은 최대 5개까지 선택할 수 있어요.');return;}data.filters.styleTags=id?setStyleFilter(data.filters.styleTags,id):[];persist();render();}
 if(a==='distance'){data.filters.distanceMeters=id?Number(id):null;panel='';persist();render();if(id)toast('매장 좌표가 없어 실제 반경 필터 결과를 표시할 수 없어요.');}
 if(a==='toggle'){data.filters[id]=!data.filters[id];persist();render();}
 if(a==='pin'){panel='';if(selected===id){if(id==='afterdark'){toast('AFTERDARK는 상세 화면이 없는 시연용 매장입니다.');return;}go('/preview/'+id);}else{selected=id;render();}}
 if(a==='zoom'){mapPose.scale=Math.max(.5,Math.min(3,mapPose.scale+Number(b.dataset.step)*.25));app.querySelector('.map-scene').style.transform=`translate(${mapPose.x}px,${mapPose.y}px) scale(${mapPose.scale})`;}
 if(a==='locate'){if(!navigator.geolocation){toast('이 브라우저에서는 위치 확인을 지원하지 않아요.');return;}navigator.geolocation.getCurrentPosition(()=>toast('현재 위치 권한을 확인했어요. 매장 좌표가 없어 지도는 시연 화면으로 유지됩니다.'),()=>toast('위치 권한을 사용할 수 없어 시연 지도를 표시합니다.'),{timeout:8000});}
 if(a==='close-preview')go('/map');
 if(a==='preview-photo'){galleryState['preview-'+id]=Number(b.dataset.index);render();}
 if(a==='shop-photo'){const s=shopBy(id);galleryState['shop-'+id]=((galleryState['shop-'+id]??1)-1+Number(b.dataset.step)+s.galleryCount)%s.galleryCount+1;render();}
 if(a==='product-photo'){galleryState['product-'+id]=Number(b.dataset.index);render();}
 if(a==='category'){shopCategory=id;render();}
 if(a==='feed-photo')toast('피드 확대 화면은 제공되지 않았어요. 상품 탭에서 상세 상품을 확인해주세요.');
 if(a==='unavailable')toast('이 상품의 상세 정보는 준비 중입니다.');
 if(a==='story-step'){const s=shopBy(r.id),types=['new','today','sale','info'],count=r.sub==='new'?s.newCount:r.sub==='sale'?s.saleCount:1,next=storyIndex+Number(b.dataset.step);if(next<0||next>=count){storyIndex=0;const ti=types.indexOf(r.sub)+Number(b.dataset.step);if(ti<0||ti>=types.length)go('/shop/'+s.id+'/feed');else go('/story/'+s.id+'/'+types[ti]);}else{storyIndex=next;render();}}
 if(a==='story-product'){if(id==='ototo'&&b.dataset.type==='new'&&b.dataset.index==='1')go('/product/ototo-01');else toast('이 스토리의 연결 상품 정보는 준비 중입니다.');}
 if(a==='eye'){const input=b.parentElement.querySelector('input'),show=input.type==='password';input.type=show?'text':'password';b.setAttribute('aria-pressed',String(show));b.setAttribute('aria-label',show?'비밀번호 가리기':'비밀번호 보기');}
 if(a==='social')toast(`${b.dataset.provider} 로그인은 인증 연동 전입니다. 시연용 로그인을 이용해주세요.`);
 if(a==='password-help')toast('실제 계정 인증 전이라 비밀번호 찾기를 사용할 수 없어요.');
 if(a==='gate-login'||a==='gate-signup'){sessionStorage.setItem('nw3-return',r.path);go(a==='gate-login'?'/login':'/signup');}
 if(a==='gate-later')go('/product/'+r.id);
 if(a==='continue')continueAfterAuth();
 if(a==='region'){region=id;render();}
 if(a==='style-list-filter')go('/explore/styles'+(id!==''?'/'+id:''));
 if(a==='new-filter'){listFilter=id;render();}
 if(a==='style-results')toast('이 스타일의 매장 목록 화면은 제공되지 않았어요.');
 if(a==='place-info'){const s=popularShops.concat(newShops).find(x=>x.id===id);toast(s.name+' · 상세 화면은 준비 중입니다.');}
 if(a==='notifications')toast('알림 서비스는 연동 전입니다.');
 if(a==='setting-info')toast(b.dataset.id+' 기능은 연동 전입니다.');
 if(a==='logout'){auth=null;sessionStorage.removeItem('nw3-auth');localStorage.removeItem('nw3-auth');sessionStorage.removeItem('nw3-return');go('/my');toast('로그아웃했어요.');}
 if(a==='cancel-reservation'){const record=bucket().reservations.find(x=>x.id===id);if(record){record.status='CANCELLED';persist();render();toast('시연 예약을 취소했어요.');}}
});
app.addEventListener('input',e=>{if(e.target.id==='map-search'){data.filters.search=e.target.value;persist();app.querySelector('#map-pins').innerHTML=mapPins();}const form=e.target.closest('#reserve-form');if(form){const p=productBy(form.dataset.product),values=Object.fromEntries(new FormData(form));sessionStorage.setItem('nw3-draft-reserve-'+p.id,JSON.stringify(values));}});
app.addEventListener('change',e=>{if(e.target.name==='date'&&e.target.closest('#reserve-form')){const form=e.target.closest('form'),p=productBy(form.dataset.product),select=form.elements.time;select.innerHTML='<option value="">방문 시간을 선택해주세요.</option>'+futureSlots(shopBy(p.shopId),e.target.value).map(t=>`<option>${t}</option>`).join('');}});
app.addEventListener('submit',async e=>{e.preventDefault();const form=e.target,values=Object.fromEntries(new FormData(form)),error=form.querySelector('.form-error');if(!error)return;error.textContent='';
 if(form.id==='login-form'||form.id==='signup-form'){if(busy)return;if(form.id==='login-form'){if(!/^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(values.email??'')||!values.password){error.textContent='시연용 이메일 형식과 비밀번호를 입력해 주세요.';return;}}else{const validation=validateSignup({...values,age:!!values.age,terms:!!values.terms,privacy:!!values.privacy});if(!validation.valid){error.textContent=Object.values(validation.errors).join(' ');return;}}
 busy=true;form.querySelector('[type="submit"]').disabled=true;try{await demoLogin(values.email,values.nickname,!!values.remember);form.reset();if(form.id==='signup-form')go('/signup-complete');else continueAfterAuth();}catch{error.textContent='시연 계정을 시작하지 못했어요.';busy=false;form.querySelector('[type="submit"]').disabled=false;}return;}
 if(!['reserve-form','delivery-form'].includes(form.id))return;if(!auth){render();return;}if(busy)return;
 const p=productBy(form.dataset.product),s=shopBy(p.shopId),b=bucket();const activeRecords=Object.values(data.accounts).flatMap(account=>account.reservations??[]).filter(record=>record.date>=dateInSeoul());
 if(form.id==='reserve-form'){const input={shopId:s.id,productId:p.id,date:values.date,time:values.time,people:Number(values.people)},validation=validateReservation(input,{today:dateInSeoul(),availableSlots:futureSlots(s,values.date),reservations:activeRecords,userId:auth.id});if(!validation.valid){error.textContent=Object.values(validation.errors).join(' ');return;}busy=true;b.reservations.unshift({...input,id:crypto.randomUUID(),userId:auth.id,status:'DEMO_REQUESTED',createdAt:new Date().toISOString()});sessionStorage.removeItem('nw3-draft-reserve-'+p.id);}
 else{if(!values.address?.trim()||values.payment!=='demo'){error.textContent='배송지 주소와 시연 결제 수단을 확인해주세요.';return;}busy=true;b.deliveries.unshift({id:crypto.randomUUID(),productId:p.id,shopId:s.id,status:'DEMO_REQUESTED',date:dateInSeoul(),createdAt:new Date().toISOString()});form.elements.address.value='';form.elements.note.value='';}
 persist();form.querySelector('[type="submit"]').disabled=true;const status=form.querySelector('.request-result');status.innerHTML='시연 신청이 저장되었습니다. 실제 '+(form.id==='reserve-form'?'매장 예약':'결제·배송')+'은 진행되지 않습니다. '+link('/my','MY에서 확인 →');status.focus();toast('시연 신청이 저장됐어요.');
});
document.addEventListener('keydown',e=>{const gate=app.querySelector('.auth-gate');if(gate&&e.key==='Tab'){const targets=[...gate.querySelectorAll('button')];if(e.shiftKey&&document.activeElement===targets[0]){e.preventDefault();targets.at(-1).focus();}else if(!e.shiftKey&&document.activeElement===targets.at(-1)){e.preventDefault();targets[0].focus();}}if(e.key==='Escape'){if(route().view==='preview')go('/map');else if(route().view==='story')go('/shop/'+route().id+'/feed');else if(panel){panel='';render();}}});
window.addEventListener('hashchange',()=>{storyIndex=0;panel='';render();});
window.addEventListener('popstate',()=>{storyIndex=0;panel='';render();});
window.addEventListener('storage',e=>{if(e.key==='nw3-data'){data={...initial(),...read('nw3-data',{})};render();}if(e.key==='nw3-auth'){auth=read('nw3-auth',null)??read('nw3-auth',null,sessionStorage);render();}});
